∀ {ι : Type u_1} {B : Type u_2} {V : Type u_3} [inst : TopologicalSpace B]
  [inst_1 : NormedAddCommGroup V] [inst_2 : NormedSpace ℝ V] (Z : VectorBundleCore ℝ B V ι),
  TopologicalSpace.IsOpenCover fun i => { carrier := Z.baseSet i, is_open' := ⋯ }

∀ (a : QuaternionicSymmetry.ManifoldTwistorSphereBundle.coefficientSphere) (r : ℝ) {v : Fin 3 → ℝ},
  v ∈ {v | QuaternionicSymmetry.ManifoldTwistorVerticalComplex.VerticalVector a v} →
    r • v ∈ {v | QuaternionicSymmetry.ManifoldTwistorVerticalComplex.VerticalVector a v}

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] {M : Type u_2}
  [inst_2 : TopologicalSpace M] [inst_3 : ChartedSpace E M]
  [IsManifold (modelWithCornersSelf ℝ E) (↑⊤) M], IsManifold (modelWithCornersSelf ℝ E) 1 M

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] {M : Type u_2}
  [inst_2 : TopologicalSpace M] [inst_3 : ChartedSpace E M]
  [IsManifold (modelWithCornersSelf ℝ E) (↑⊤) M], IsManifold (modelWithCornersSelf ℝ E) (↑⊤ + 1) M

∀ (d : ℕ) (i : Fin (d + 1)),
  Nonempty
    ↥{ carrier := QuaternionicSymmetry.ComplexProjectiveTopology.affineDomain d i, is_open' := ⋯ }

∀ {B : Type u_2} {B' : Type u_1} [inst : TopologicalSpace B] {ι : Type u_3}
  (Z : VectorBundleCore ℂ B ℂ ι) (f : B' → B) (i : ι),
  ∀ x ∈ f ⁻¹' Z.baseSet i, ∀ (v : ℂ), (Z.coordChange i i (f x)) v = v

nodes.doc:
A holomorphic line-bundle isomorphism stated on two arbitrary covers.
The scalar maps and their inverse are holomorphic on each intersection;
compatibility is imposed on *all* common four-chart overlaps.

nodes.type:
∀ {B : Type u_1} [inst : TopologicalSpace B] {ι : Type u_2} {κ : Type u_3}
  (Z : VectorBundleCore ℂ B ℂ ι) (W : VectorBundleCore ℂ B ℂ κ) (x : B),
  x ∈ Z.baseSet (Z.indexAt x, W.indexAt x).1 ∧ x ∈ W.baseSet (Z.indexAt x, W.indexAt x).2

∀ {B : Type u_3} [inst : TopologicalSpace B] {ι : Type u_1} {κ : Type u_2}
  (Z : VectorBundleCore ℂ B ℂ ι) (W : VectorBundleCore ℂ B ℂ κ) (p : ι × κ),
  IsOpen (Z.baseSet p.1 ∩ W.baseSet p.2)

∀ {ι : Type u_3} {B : Type u_1} {V : Type u_2} [inst : TopologicalSpace B]
  [inst_1 : NormedAddCommGroup V] [inst_2 : InnerProductSpace ℝ V] {Z : VectorBundleCore ℝ B V ι}
  (x : B), x ∈ Z.baseSet (Z.indexAt x)

∀ {ι : Type u_3} {B : Type u_1} {V : Type u_2} [inst : TopologicalSpace B]
  [inst_1 : NormedAddCommGroup V] [inst_2 : InnerProductSpace ℝ V] {Z : VectorBundleCore ℝ B V ι}
  (i : ι), IsOpen (Z.baseSet i)

∀ {E : Type u_1} {H : Type u_2} {M : Type u_3} [inst : NormedAddCommGroup E]
  [inst_1 : InnerProductSpace ℝ E] [inst_2 : TopologicalSpace H] {I : ModelWithCorners ℝ E H}
  [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I 1 M]
  {n : WithTop ℕ∞} [inst_6 : IsManifold I (n + 1) M]
  (Q : QuaternionicSymmetry.ManifoldQuaternionicMetric.SmoothQuaternionicHermitianTangent) (x : M),
  Bornology.IsVonNBounded ℝ {v | ((Q.tangentMetricForm x) v) v < 1}

∀ {κ : Type u_1} [inst : Fintype κ] [inst_1 : DecidableEq κ] (J : Matrix κ κ ℂ)
  {u : ↥(Matrix.unitaryGroup κ ℂ)},
  u ∈ {u | (↑u).transpose * J * ↑u = J} → u⁻¹ ∈ {u | (↑u).transpose * J * ↑u = J}
